/// <summary>
/// One off job to disable indexes
/// </summary>
class METDisableIndexes
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        void disableIndex(str _tableName, str _indexName)

        {
            str strSQL;
            Connection conn;
            SqlStatementExecutePermission permission;

            strSQL = strFmt('ALTER INDEX [%1] ON [DBO].[%2] DISABLE;', _indexName, _tableName);
            try
            {
                permission = new SqlStatementExecutePermission(strSQL);
                conn = new Connection();
                permission = new SqlStatementExecutePermission(strSQL);
                permission.assert();
                conn.createStatement().executeUpdate(strSQL);

                // the permissions needs to be reverted back to original condition.
                CodeAccessPermission::revertAssert();
            }
            catch
            {
                error(strFmt('Error executing "%1"', strSQL));
                CodeAccessPermission::revertAssert();
            }
        }

        disableIndex(tableStr(LedgerJournalEntityStaging), 'I_5355STAGINGREVERSEENTRIESIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869VENDTRANSIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869TAX1099FIELDSIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BANKRESPWORKERID_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BANKCURRENCYTRANSFERLOG_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869POOLRECID');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869DIRECTDEBITMANDATEIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869CUSTOMERTRANSIDIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869VOUCHERVOUCHERTYPE_CNIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BUDGETSOURCEIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869PAYMINSTRUCTIONIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869LEDGERVOUCHERTYPE_CNIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869SALESORDERIDIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869ACCOUNTAGREEMENT_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869FURTHERPOSTINGRECIDIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869PLTAXDUETABLEIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BANKAGREEMENTEXT_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869VENDINVOICEDECLARATION_ISIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'ndx_ATuneJOURNALNUMVOUCHERDATAAREAIDPARTITION');

        //MPJ_19216_18920_Performance tuning DCP 07/02/2022
        disableIndex(tableStr(GENERALJOURNALACCOUNTENTRY), 'I_7542GENERALJOURNALENTRYIDX');
        disableIndex(tableStr(GENERALJOURNALENTRY), 'I_20085TRANSFERIDX');
        disableIndex(tableStr(SPECTRANS), 'I_12104SPECIDX');
        disableIndex(tableStr(SUBLEDGERVOUCHERGENERALJOURNALENTRY), 'I_2262GENERALJOURNALENTRYIDX');

        //21280 Index Performance AMEX DCP 21/03/2022
        disableIndex(tableStr(TaxTrans), 'ndx_ATuneTRANSDATEVOUCHERDATAAREAIDPARTITIONTAXDIRECTION');
        disableIndex(tableStr(TaxTrans), 'I_4569VOUCHERDATEIDX');
        disableIndex(tableStr(SpecTrans), 'I_12104REFIDX');
        disableIndex(tableStr(SpecTrans), 'ndx_ATuneFULLSETTLEMENTREFTABLEIDSPECCOMPANYSPECRECIDSPECTABLEIDPARTITION');
        disableIndex(tableStr(SpecTrans), 'ndx_ATuneSPECCOMPANYSPECTABLEIDPARTITION');
        
        info('Disable indexes job completed.');
    }
